def get_home():
    h = os.environ.get("HOME", None)
    if h is not None and h != "":
        return h
    # fallback to passwd
    try:
        return pwd.getpwuid(os.getuid()).pw_dir
    except Exception:
        return "/root"

def get_config_dir():
    xdg = os.environ.get("XDG_CONFIG_HOME", None)
    if xdg is not None and xdg != "" and xdg.startswith("/"):
        return xdg
    return os.path.join(get_home(), ".config")

def get_data_dir():
    xdg = os.environ.get("XDG_DATA_HOME", None)
    if xdg is not None and xdg != "" and xdg.startswith("/"):
        return xdg
    return os.path.join(get_home(), ".local", "share")

def config_file_path():
    return os.path.join(get_config_dir(), "jot", "config")

